let WARMUPS = [{"name": "下肢退阶热身", "applies": "周一/周三/周五（腿与后链日）", "steps": "1) 仰卧呼吸：鼻吸4秒-停2秒-口呼6秒，5次×2\n2) 仰卧雨刷（髋内外旋）：来回10次×2（腰不扭）\n3) 仰卧臀桥：2×10（余力4）\n4) 坐姿足弓激活：每脚5秒×5×2（不扣脚趾）\n5) 踝背屈靠墙：每侧10–15次×1–2", "notes": "适合髋/足功能差的起步阶段；范围小、求控制"}, {"name": "上肢胸椎/肩胛退阶热身", "applies": "周二/周六（胸/肩/背日）", "steps": "1) 猫牛（胸椎）：10次×2\n2) 泡沫轴胸椎伸展（或卷毛巾）：6–8次×1–2\n3) 高位肩胛俯卧撑：10次×1–2\n4) 弹力带直臂下拉（肩胛下沉/下旋）：12–15次×2\n5) 俯身T+Y（超轻）：T10次+Y8–10次，循环×2\n6) 外旋：每侧12次×1–2；Face Pull：15次×1–2\n7) 空杠卧推：2×10（练肘位与轨迹）", "notes": "重点改善胸椎伸展与肩胛下沉/下旋控制"}, {"name": "执行规则（九阳神功简版）", "applies": "所有训练日", "steps": "余力说明：余力4≈很轻松；余力3≈还能多做3次；余力2≈还能多做2次；余力1≈还能多做1次。\n主项/大动作：动作一乱先减重；增肌期主项常用余力3–4。\n静息心率高5–10或连续2–3天偏高：当天减量5–10%或提前减载。", "notes": "疲劳管理与加重规则"}];
const KEY='xuhui_training_v2_dailygrid';
let state = JSON.parse(localStorage.getItem(KEY)||'{}');
if(!state.logs) state.logs=[];
if(state.currentIndex===undefined) state.currentIndex=0;
if(!state.startDate) state.startDate = new Date().toISOString().slice(0,10);
if(!state.settings) state.settings={mainRest:180,assistRest:90};
if(!state.dateAnchors) state.dateAnchors={}; // 训练序号 -> 实际标注日期。后续日期会从最近锚点继续顺延。
if(!state.actualDates) state.actualDates={}; // 训练序号 -> 实际训练发生日期；一旦写入就优先显示和归档。
if(!state.customWarmups) state.customWarmups={}; // 按训练目的保存：胸训/腿训/通用
if(!state.currentWorkoutDrafts) state.currentWorkoutDrafts={}; // 按训练序号保存尚未完成的重量/次数/余力草稿。
if(state.selectedCalendarIndex===undefined) state.selectedCalendarIndex=state.currentIndex||0;
if(state.quickNote===undefined) state.quickNote='';
if(state.currentSessionNote===undefined) state.currentSessionNote=state.draftNote||state.quickNote||'';
if(!state.noteArchive) state.noteArchive=[];
if(state.keepNoteForNext===undefined) state.keepNoteForNext=false;
if(typeof migrateOldImportedDataIfNeeded === 'function') migrateOldImportedDataIfNeeded();
try{
  var importedPlan = JSON.parse(localStorage.getItem(KEY+'_importedPlan')||'null');
  var importedWarmups = JSON.parse(localStorage.getItem(KEY+'_importedWarmups')||'null');
  if(Array.isArray(importedPlan) && importedPlan.length){ PLAN = importedPlan; }
  if(Array.isArray(importedWarmups) && importedWarmups.length){ WARMUPS = importedWarmups; }
}catch(e){}
try{ if(ensureDateMigration()) saveState(); }catch(e){}
try{ state.logs=getBackupLogsFromState(state); state.exerciseHistory=buildExerciseHistoryFromLogs(state.logs); }catch(e){}
try{ if(dedupeTemplateLibraries()) saveState(); }catch(e){}
let activeSet = null, timerLeft=180, timerBase=180, timerId=null;
let rowTimers = {}; // 每一组都能独立显示自己的倒计时；实际同时只跑一个，避免训练时多个铃同时响。
let activeTimerContext = null; // 用真实结束时间校准，切出手机后回来不丢时间。

function saveState(){localStorage.setItem(KEY, JSON.stringify(state));}

function inferExerciseCategory(name){
  var n=String(name||'').toLowerCase();
  if(/卧推|推胸|飞鸟|夹胸|俯卧撑|胸/.test(n)) return '胸';
  if(/推举|侧平举|前平举|面拉|face|landmine|肩/.test(n)) return '肩';
  if(/划船|下拉|引体|背|pull|row|lat/.test(n)) return '背';
  if(/硬拉|rdl|罗马尼亚|臀桥|臀推|山羊|后链|good morning/.test(n)) return '后链/硬拉';
  if(/深蹲|腿举|腿弯举|腿屈伸|登阶|分腿蹲|箭步|提踵|前蹲|背蹲|高脚杯|泽奇|箱式/.test(n)) return '腿';
  if(/臀|髋外展|蚌式/.test(n)) return '臀腿';
  if(/死虫|卷腹|支撑|平板|核心|抗旋|pallof|哥本哈根/.test(n)) return '核心';
  if(/弯举|三头|二头|臂屈伸|下压|手臂/.test(n)) return '手臂';
  return '通用';
}
function inferWarmupCategory(name){
  var n=String(name||'').toLowerCase();
  if(/足|踝|背屈|足弓|小腿|提踵/.test(n)) return '足踝';
  if(/髋|臀|90\/90|雨刷|蚌式/.test(n)) return '髋';
  if(/胸椎|猫牛|泡沫轴|伸展|旋转/.test(n)) return '胸椎';
  if(/肩胛|直臂下拉|俯卧撑|下沉|face|面拉/.test(n)) return '肩胛';
  if(/外旋|内旋|肩袖|弹力带/.test(n)) return '肩袖';
  if(/死虫|支撑|核心|呼吸|抗旋/.test(n)) return '核心';
  if(/深蹲|腿|登阶|弓步|膝|髋/.test(n)) return '下肢';
  if(/卧推|推|拉|肩|背|胸/.test(n)) return '上肢';
  return '通用';
}
function normalizeTemplateKey(x){
  return String(x||'')
    .trim()
    .toLowerCase()
    .replace(/[（）]/g,function(ch){return ch==='（'?'(':')';})
    .replace(/\([^)]*\)/g,'')
    .replace(/[｜|].*$/,'')
    .replace(/(?:余力|rir|建议重量|建议|休息|休)\s*[:：]?\s*[\d.\-至~～]*\s*(?:kg|公斤|lb|秒|s|分钟|min)?/gi,'')
    .replace(/\d{1,2}\s*(?:组\s*)?[x×＊*]\s*[\d.\-至~～]+(?:\s*(?:次|秒|s|分钟|min|呼吸))?(?:\/侧)?/gi,'')
    .replace(/\d{1,2}\s*组/gi,'')
    .replace(/\d{1,3}\s*(?:秒|s)(?:\/侧)?(?:\s*[x×＊*]\s*\d{1,2})?/gi,'')
    .replace(/\d+(?:\.\d+)?\s*(?:kg|公斤|lb)/gi,'')
    .replace(/\s+/g,'')
    .replace(/[　]/g,'')
    .trim();
}
function safeDomId(prefix,index,name){
  var key=normalizeTemplateKey(name)||'item';
  key=key.replace(/[^\w\u4e00-\u9fa5]/g,'_').slice(0,48)||'item';
  return prefix+'_'+(index||0)+'_'+key;
}
