function parseExercises(text){
  return (text||'').split('\n').filter(function(x){return x.trim()&&!x.includes('【本周提示】');}).map(function(line,i){
    if(typeof parseExerciseLine === 'function'){
      var parsed = parseExerciseLine(line);
      if(parsed && parsed.valid){
        return {
          name:parsed.name,
          line:line.trim(),
          sets:parsed.sets||1,
          reps:parsed.reps||'',
          rir:parsed.rir||'',
          duration:parsed.duration||'',
          suggestedWeight:parsed.suggestedWeight||'',
          rest:parsed.rest||null,
          isMain:i===0,
          index:i
        };
      }
    }
    var raw=line.trim();
    var clean=raw.replace(/^[\d]+[\)\.、]\s*/,'').trim();
    var name=clean, sets=1, reps='', rir='';

    // 识别：余力2-3 / RIR2-3 / （余力2-3）/ (RIR 2-3)
    var rirM=clean.match(/(?:余力|RIR)\s*[:：]?\s*([\d–\-~至]+(?:\.\d+)?)/i);
    if(rirM) rir=(rirM[1]||'').trim();

    // 识别：3x5 / 3×5 / 3*5 / 3组×5次。前面=组数，后面=次数。
    var setRepM=clean.match(/(\d{1,2})\s*(?:组\s*)?[x×＊*]\s*([\d–\-~至]+)(?:\s*次)?/i);
    if(!setRepM){
      // 兼容：3组｜5 / 3组 5次
      setRepM=clean.match(/(\d{1,2})\s*组\s*(?:[｜|,，\s]+)\s*([\d–\-~至]+)(?:\s*次)?/i);
    }
    if(setRepM){
      sets=parseInt(setRepM[1],10)||1;
      reps=String(setRepM[2]||'').trim();
    }

    // 名称：去掉组次、余力、建议重量、休息等执行参数，但保留“技术”等动作说明。
    name=clean
      .replace(/（\s*(?:余力|RIR)[^）]*）/gi,'')
      .replace(/\(\s*(?:余力|RIR)[^\)]*\)/gi,'')
      .replace(/\d{1,2}\s*(?:组\s*)?[x×＊*]\s*[\d–\-~至]+(?:\s*次)?/i,'')
      .replace(/\d{1,2}\s*组\s*(?:[｜|,，\s]+)\s*[\d–\-~至]+(?:\s*次)?/i,'')
      .replace(/(?:余力|RIR)\s*[:：]?\s*[\d–\-~至]+(?:\.\d+)?/gi,'')
      .replace(/[｜|]\s*建议[^｜|]*/g,'')
      .replace(/[｜|]\s*休息[^｜|]*/g,'')
      .replace(/建议\s*[\d\.]+\s*kg/gi,'')
      .replace(/休息\s*[:：]?\s*[\d–\-~至]+\s*(?:秒|分钟|min|s)?/gi,'')
      .replace(/[｜|]+\s*$/g,'')
      .replace(/\s+/g,' ')
      .trim();
    if(!name) name=clean;

    return {name:name,line:raw,sets:sets,reps:reps,rir:rir,isMain:i===0,index:i};
  });
}
function getWorkout(){return PLAN[Math.max(0,Math.min(state.currentIndex,PLAN.length-1))];}
