/* ===== 手机导航稳定版 + 训练日顺序移动 ===== */
function persistCurrentPlanOrder(){
  try{ localStorage.setItem(KEY+'_importedPlan', JSON.stringify(PLAN)); }catch(e){}
}
function moveCurrentTraining(delta){
  delta = Number(delta)||0;
  if(!delta) return;
  var i = Math.max(0, Math.min(PLAN.length-1, state.currentIndex||0));
  var j = i + delta;
  if(j < 0 || j >= PLAN.length){
    alert(delta<0 ? '已经是第一练，不能再前移。' : '已经是最后一练，不能再后推。');
    return;
  }
  var before = PLAN[i] && PLAN[i]['训练主题'] ? PLAN[i]['训练主题'] : ('#'+(i+1));
  var other = PLAN[j] && PLAN[j]['训练主题'] ? PLAN[j]['训练主题'] : ('#'+(j+1));
  var tmp = PLAN[i]; PLAN[i] = PLAN[j]; PLAN[j] = tmp;
  state.currentIndex = j; // 跟随“被移动的当前训练”一起移动，避免你不知道自己挪的是谁
  state.dateAnchors = state.dateAnchors || {};
  var anchors=state.dateAnchors, a=anchors[i], b=anchors[j];
  if(b!==undefined) anchors[i]=b; else delete anchors[i];
  if(a!==undefined) anchors[j]=a; else delete anchors[j];
  state.actualDates = state.actualDates || {};
  var actuals=state.actualDates, aa=actuals[i], bb=actuals[j];
  if(bb!==undefined) actuals[i]=bb; else delete actuals[i];
  if(aa!==undefined) actuals[j]=aa; else delete actuals[j];
  persistCurrentPlanOrder();
  saveState();
  rebuild();
  if(!document.getElementById('calendar').classList.contains('hidden')) renderCalendar();
  alert((delta<0?'已前移：':'已后推：') + before + '，与 ' + other + ' 交换位置。');
}
function promoteNextTrainingToToday(){
  var i=Math.max(0,Math.min(PLAN.length-1,state.currentIndex||0));
  if(i>=PLAN.length-1){ alert('后面没有下一练了。'); return; }
  var tmp=PLAN[i]; PLAN[i]=PLAN[i+1]; PLAN[i+1]=tmp;
  state.dateAnchors=state.dateAnchors||{};
  var a=state.dateAnchors[i], b=state.dateAnchors[i+1];
  if(b!==undefined) state.dateAnchors[i]=b; else delete state.dateAnchors[i];
  if(a!==undefined) state.dateAnchors[i+1]=a; else delete state.dateAnchors[i+1];
  state.actualDates=state.actualDates||{};
  var aa=state.actualDates[i], bb=state.actualDates[i+1];
  if(bb!==undefined) state.actualDates[i]=bb; else delete state.actualDates[i];
  if(aa!==undefined) state.actualDates[i+1]=aa; else delete state.actualDates[i+1];
  persistCurrentPlanOrder(); saveState(); rebuild(); renderCalendar();
  alert('已把下一练提前到今天，原本今天这一练顺延到下一位。');
}
(function(){
  var oldShowTab = window.showTab;
  window.showTab = function(id){
    var pages=['today','calendar','history','settings','rmcalc','importer'];
    for(var i=0;i<pages.length;i++){
      var el=document.getElementById(pages[i]);
      if(el) el.classList.toggle('hidden', pages[i]!==id);
    }
    var btns=document.querySelectorAll('#topTabs .tab,.tabs .tab');
    for(var j=0;j<btns.length;j++){
      var on=(btns[j].getAttribute('data-tab')===id);
      btns[j].classList.toggle('isOn',on);
      btns[j].classList.toggle('primary',on);
    }
    try{
      var ms=document.getElementById('mobileTabSelect'); if(ms) ms.value=id;
      if(id==='calendar')renderCalendar();
      if(id==='history')renderHistory();
      if(id==='settings')renderSettings();
    }catch(e){ console.error(e); }
  };
  function bindMobileTabs(){
    var btns=document.querySelectorAll('#topTabs .tab,.tabs .tab');
    for(var i=0;i<btns.length;i++){
      (function(btn){
        if(btn.__mobileBound) return;
        btn.__mobileBound=true;
        var id=btn.getAttribute('data-tab');
        if(!id) return;
        var handler=function(ev){
          if(ev){ ev.preventDefault(); ev.stopPropagation(); }
          window.showTab(id);
        };
        btn.addEventListener('touchend', handler, {passive:false});
        btn.addEventListener('pointerup', handler, false);
        btn.addEventListener('click', handler, false);
      })(btns[i]);
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', bindMobileTabs);
  else bindMobileTabs();
  setTimeout(bindMobileTabs,300);
  setTimeout(bindMobileTabs,1000);
})();


function bindMobileSelectNav(){
  var ms=document.getElementById('mobileTabSelect');
  if(!ms || ms.__navBound) return;
  ms.__navBound=true;
  var handler=function(){ window.showTab ? window.showTab(ms.value) : showTab(ms.value); };
  ms.addEventListener('change', handler, false);
  ms.addEventListener('input', handler, false);
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', bindMobileSelectNav); else bindMobileSelectNav();
setTimeout(bindMobileSelectNav,300);

function forceMobileNav(){
  var ms=document.getElementById('mobileTabSelect');
  var id=ms ? ms.value : 'today';
  if(typeof window.showTab==='function') window.showTab(id); else showTab(id);
  try{ window.scrollTo({top:0,behavior:'smooth'}); }catch(e){ window.scrollTo(0,0); }
}
(function(){
  function bindForceNav(){
    var ms=document.getElementById('mobileTabSelect');
    var go=document.getElementById('mobileTabGo');
    if(ms && !ms.__forceBound){
      ms.__forceBound=true;
      ['change','input'].forEach(function(ev){ms.addEventListener(ev,function(){forceMobileNav();},false);});
    }
    if(go && !go.__forceBound){
      go.__forceBound=true;
      ['click','touchend','pointerup'].forEach(function(ev){go.addEventListener(ev,function(e){if(e){e.preventDefault();e.stopPropagation();}forceMobileNav();},false);});
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', bindForceNav); else bindForceNav();
  setTimeout(bindForceNav,300); setTimeout(bindForceNav,1000);
})();



/* ===== 日期队列滚动修复3：进入日历后定位到当前选中/当前应练 ===== */
function getCalendarFocusIndex(){
  var idx;
  if(state && state.selectedCalendarIndex !== undefined && state.selectedCalendarIndex !== null){
    idx = Number(state.selectedCalendarIndex);
  }else{
    idx = Number(state.currentIndex || 0);
  }
  if(isNaN(idx)) idx = 0;
  return Math.max(0, Math.min(PLAN.length-1, idx));
}
function findScrollableParent(el){
  var p = el ? el.parentElement : null;
  while(p && p !== document.body && p !== document.documentElement){
    var cs = window.getComputedStyle(p);
    var oy = cs.overflowY;
    if((oy === 'auto' || oy === 'scroll') && p.scrollHeight > p.clientHeight + 10) return p;
    p = p.parentElement;
  }
  return null;
}
function scrollCalendarToIndex(i){
  var cal = document.getElementById('cal');
  if(!cal) return;
  i = Math.max(0, Math.min(PLAN.length-1, Number(i)||0));
  var node = cal.querySelector('[data-cal-index="'+i+'"]');
  if(!node) return;
  var parent = findScrollableParent(node);
  try{
    if(parent){
      var top = node.offsetTop - parent.offsetTop - 12;
      parent.scrollTo({top: Math.max(0, top), behavior:'smooth'});
    }else{
      var sticky = document.querySelector('#calendar .calendarSticky');
      var offset = sticky ? Math.min(260, sticky.getBoundingClientRect().height + 16) : 90;
      var y = window.pageYOffset + node.getBoundingClientRect().top - offset;
      window.scrollTo({top: Math.max(0, y), behavior:'smooth'});
    }
  }catch(e){
    try{ node.scrollIntoView({behavior:'smooth', block:'center'}); }catch(_){ node.scrollIntoView(true); }
  }
}
function scrollCalendarToCurrent(){
  scrollCalendarToIndex(getCalendarFocusIndex());
}
function refreshCalendarAndFocus(delay){
  renderCalendar();
  setTimeout(function(){ scrollCalendarToIndex(getCalendarFocusIndex()); }, delay || 160);
  setTimeout(function(){ scrollCalendarToIndex(getCalendarFocusIndex()); }, (delay || 160) + 420);
}
(function(){
  var oldShow = window.showTab || showTab;
  window.showTab = function(id){
    oldShow(id);
    if(id === 'calendar'){
      setTimeout(function(){ scrollCalendarToIndex(getCalendarFocusIndex()); }, 180);
      setTimeout(function(){ scrollCalendarToIndex(getCalendarFocusIndex()); }, 650);
    }
  };
  window.goCurrentPending = function(){
    state.selectedCalendarIndex = state.currentIndex;
    saveState();
    refreshCalendarAndFocus(120);
  };
  window.anchorSelectedDate = function(){
    var inp=document.getElementById('selectedActualDate');
    if(!inp || !inp.value){ alert('先选择一个日期。'); return; }
    var selected=getCalendarFocusIndex();
    markActualTrainingDate(selected, inp.value, {noSave:true});
    saveState();
    refreshCalendarAndFocus(120);
  };
})();

